import{_ as r,c as l,o as i,af as e,at as s,au as t,av as o,aw as m,ax as _,ay as c,az as h,aA as n,aB as b,aC as g,aD as p,aE as d,aF as u,aG as f,aH as q}from"./chunks/framework.CI8A52oi.js";const D=JSON.parse('{"title":"如何游玩服务器","description":"","frontmatter":{},"headers":[],"relativePath":"regisbs.md","filePath":"regisbs.md"}'),P={name:"regisbs.md"};function k(x,a,C,A,T,E){return i(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="如何游玩服务器" tabindex="-1">如何游玩服务器 <a class="header-anchor" href="#如何游玩服务器" aria-label="Permalink to “如何游玩服务器”">​</a></h1><h2 id="加入qq群" tabindex="-1">加入qq群 <a class="header-anchor" href="#加入qq群" aria-label="Permalink to “加入qq群”">​</a></h2><ul><li><p>如果您从其他渠道获得了本服务器的文档链接，您需要先加入<strong>服务器官方群</strong> <a href="https://qm.qq.com/q/5csKgUEZ3O" target="_blank" rel="noreferrer">https://qm.qq.com/q/5csKgUEZ3O</a> 以正常游玩</p></li><li><p>如果您使用PC（JAVA版），请继续看，如果您使用基岩版，登录微软账户之后可直接填写服务器信息游玩</p></li></ul><h2 id="注册账号" tabindex="-1">注册账号 <a class="header-anchor" href="#注册账号" aria-label="Permalink to “注册账号”">​</a></h2><ol><li>打开以下链接<br><strong>红白阁-Redwhite:</strong> <a href="https://bs.samuge.red" target="_blank" rel="noreferrer">https://bs.samuge.red</a></li><li>左键点击现在注册<br><img src="'+s+'" alt=""></li><li>您将看到如下页面，按照要求填写您的信息<br><img src="'+t+'" alt=""></li></ol><ul><li>如果您没有邮箱，您可以直接将您的QQ号@qq.com作为邮箱号使用</li><li>例如：123123123@qq.com</li><li>“游戏内角色名”就是您在Minecraft中的玩家ID，注册成功后，它将作为您的身份在游戏中显示</li><li>“游戏内角色名”不允许重名，如果您遇到下图的情况，请更换角色名后重试 <img src="'+o+'" alt=""></li></ul><ol start="4"><li>如果没有问题，过一小会您会看到如下页面 <img src="'+m+'" alt=""><br> 这说明您已经注册成功，请继续根据教程说明完成设置</li></ol><ul><li>如果遇到问题请联系群内管理员</li></ul><h2 id="使用外置登录" tabindex="-1">使用外置登录 <a class="header-anchor" href="#使用外置登录" aria-label="Permalink to “使用外置登录”">​</a></h2><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><ul><li>使用本站自带的拖拽方式，将这个按钮拖拽到您的启动器界面<br><img src="'+_+'" alt=""></li><li>这里以PCL为例，当拖拽按钮进入后，输入您的账户密码，然后单击启动游戏<br><img src="'+c+'" alt=""></li><li>加入服务器即可<br></li></ul><h3 id="方法二-同样以pcl为例" tabindex="-1">方法二（同样以PCL为例） <a class="header-anchor" href="#方法二-同样以pcl为例" aria-label="Permalink to “方法二（同样以PCL为例）”">​</a></h3><ul><li></li></ul><p><img src="'+h+'" alt=""> * <img src="'+n+'" alt=""> * <img src="'+b+'" alt=""><br> 此处的两条链接分别为<br><a href="https://bs.samuge.red/api/yggdrasil" target="_blank" rel="noreferrer">https://bs.samuge.red/api/yggdrasil</a><br><a href="https://bs.samuge.red/auth/register" target="_blank" rel="noreferrer">https://bs.samuge.red/auth/register</a><br></p><ul><li>登录后启动即可<br></li></ul><h2 id="连接到服务器" tabindex="-1">连接到服务器 <a class="header-anchor" href="#连接到服务器" aria-label="Permalink to “连接到服务器”">​</a></h2><ul><li><strong>以1.21.4为例</strong></li><li>在启动器点击启动游戏之后，过一段时间能看到类似下图的游戏窗口，点击“多人游戏” <img src="'+g+'" alt=""><br></li><li>点击“添加服务器” <img src="'+p+'" alt=""><br></li><li>在服务器地址输入mc.samuge.red</li><li>您也可以修改服务器名称以便于区分，这是可选的 <img src="'+d+'" alt=""><br></li><li>需要注意，请检查下方“服务器资源包”按钮，确保为“询问”（如下图）或“允许”，随后点击“完成” <img src="'+u+'" alt=""><br></li><li>这时服务器列表应该出现了刚才添加的服务器，点击 <img src="'+f+'" alt=""><br></li><li>一切顺利的话，会出现下图的提示，点击“继续”即可 <img src="'+q+'" alt=""><br></li></ul>',17)])])}const V=r(P,[["render",k]]);export{D as __pageData,V as default};
